//! Raw libmpv bindings, generated by `build.rs` (bindgen over `mpv/client.h`,
//! `mpv/render.h`, `mpv/render_gl.h`; allowlist `mpv_.*` functions/types, `MPV_.*` vars).
//! C enums are module-scoped integer constants (`mpv_event_id::MPV_EVENT_FILE_LOADED`,
//! …). Use the safe wrapper in [`super`] instead of these directly.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    unsafe_op_in_unsafe_fn,
    clippy::all
)]

include!(concat!(env!("OUT_DIR"), "/mpv_bindings.rs"));
